export type WebGraphQLValue = string | number | boolean | null | readonly WebGraphQLValue[] | {
    readonly [key: string]: WebGraphQLValue;
};

export type WebGraphQLRow = Readonly<Record<string, WebGraphQLValue>>;

export type WebGraphQLParameters = Readonly<Record<string, WebGraphQLValue | undefined>>;

export type WebGraphQLOperationKind = 'query' | 'insert' | 'update' | 'delete';

export type WebGraphQLParameterKind = 'string' | 'number' | 'integer' | 'boolean' | 'json';

export interface WebGraphQLParameter {
    readonly name: string;
    /** GraphQL type notation, including list and non-null wrappers. */
    readonly type: string;
    readonly kind: WebGraphQLParameterKind;
    readonly required: boolean;
    readonly enumValues: readonly string[];
    readonly defaultValue?: WebGraphQLValue;
    readonly source: {
        readonly role: 'filter' | 'input';
        /** JSON Pointer relative to one result row. */
        readonly fieldPath: string;
        readonly operator?: string;
        /** True only for an equality predicate that constrains every filter alternative. */
        readonly identityEligible?: boolean;
    };
}

export interface WebGraphQLSelection {
    readonly name: string;
    readonly kind: 'object' | 'list' | 'connection';
    readonly children: readonly WebGraphQLSelection[];
}

export interface WebGraphQLRuntimeOperation {
    readonly id: string;
    readonly name: string;
    readonly database: string;
    readonly kind: WebGraphQLOperationKind;
    readonly rootField: string;
    /** The published schema's record type, used to match queries and mutations. */
    readonly table: string;
    readonly document: string;
    readonly parameters: readonly WebGraphQLParameter[];
    readonly selections: readonly WebGraphQLSelection[];
    readonly pagination?: {
        readonly defaultSize: number;
        readonly maxSize: number;
    };
}

export interface WebGraphQLPageInfo {
    readonly endCursor: string | null;
    readonly hasNextPage: boolean;
}

export interface WebGraphQLPage<TRow = WebGraphQLRow> {
    readonly rows: readonly TRow[];
    readonly pageInfo: WebGraphQLPageInfo;
    readonly totalCount: number | null;
}

export interface WebGraphQLMutationResult<TRow = WebGraphQLRow> {
    readonly affectedCount: number;
    readonly records: readonly TRow[];
}

export type WebGraphQLResult = WebGraphQLPage | WebGraphQLMutationResult;

export interface WebGraphQLPageOptions<TVariables = WebGraphQLParameters> {
    readonly first?: number;
    readonly after?: string | null;
    readonly variables?: TVariables;
    readonly signal?: AbortSignal;
    /** Disable result publication when an independent data-bound control owns the request. */
    readonly publish?: boolean;
}

export interface WebGraphQLMutationOptions {
    /** Set false when executing an exact variable snapshot captured earlier. */
    readonly mergeVariables?: boolean;
}

export interface WebGraphQLChange {
    readonly kind: 'parameters' | 'page' | 'session';
    readonly operationId: string;
}

export interface WebGraphQLSource {
    readonly operations: readonly WebGraphQLRuntimeOperation[];
    readonly authenticated: boolean;
    getOperation(idOrName: string): WebGraphQLRuntimeOperation | undefined;
    getVariables(idOrName: string): WebGraphQLParameters;
    getPage(idOrName: string): WebGraphQLPage | undefined;
    subscribe(listener: (change: WebGraphQLChange) => void): () => void;
    executePageById(idOrName: string, options?: WebGraphQLPageOptions): Promise<WebGraphQLPage>;
    executeMutationById(idOrName: string, variables?: WebGraphQLParameters, options?: WebGraphQLMutationOptions): Promise<WebGraphQLMutationResult>;
}

type GraphQLRequestPhase = 'Request' | 'Success' | 'Error' | 'Complete';

export interface WebGraphQLConfig extends WebNonvisualComponentOptions {
    readonly operations?: readonly WebGraphQLRuntimeOperation[];
    readonly onLifecycle?: (phase: GraphQLRequestPhase, detail: WebGraphQLEventDetail) => boolean;
}

export class WebGraphQLRequestError extends Error {
    readonly code: string;
    readonly status: number | null;
    readonly outcome: 'rejected' | 'unknown';
    constructor(message: string, code: string, status?: number | null, outcome?: 'rejected' | 'unknown');
}

export interface WebGraphQLEventDetail {
    readonly operationId: string;
    readonly operationName: string;
    readonly result?: WebGraphQLResult;
    readonly error?: Error;
}

export type WebGraphQLEventHandler<TSender> = (sender: TSender, event: CustomEvent<WebGraphQLEventDetail>) => void | Promise<void>;

type OperationName<TParameters, TResults> = Extract<keyof TParameters & keyof TResults, string>;

type OperationOf<TParameters, TResults, TResult> = {
    [TName in OperationName<TParameters, TResults>]: Extract<TResults[TName], TResult> extends never ? never : TName;
}[OperationName<TParameters, TResults>];

const graphQLOperationReference: unique symbol;

export interface WebGraphQLOperationReference<TName extends string = string, TParameters = object> {
    readonly [graphQLOperationReference]: true;
    readonly name: TName;
    readonly id: string;
    readonly parameter: {
        -readonly [TKey in keyof TParameters]-?: TParameters[TKey] | undefined;
    };
}

export type WebGraphQLExecutionOptions<TResult> = TResult extends WebGraphQLPage<unknown> ? Omit<WebGraphQLPageOptions, 'variables'> : WebGraphQLMutationOptions;

export interface WebGraphQLExecution<TParameters extends object, TResults extends object> {
    readonly operation: {
        readonly [TName in OperationName<TParameters, TResults>]: WebGraphQLOperationReference<TName, TParameters[TName]>;
    };
    execute<TName extends OperationName<TParameters, TResults>>(operation: WebGraphQLOperationReference<TName>, parameters?: TParameters[NoInfer<TName>], options?: WebGraphQLExecutionOptions<TResults[NoInfer<TName>]>): Promise<TResults[TName]>;
    setVariables<TName extends OperationName<TParameters, TResults>>(name: TName, variables: TParameters[TName]): void;
}

/** Runs project-authored GraphQL operations through the signed-in RestGo user. */
export class WebApiGraphQL<TParameters extends object = Record<string, WebGraphQLParameters>, TResults extends object = Record<string, WebGraphQLResult>> extends WebNonvisualComponent implements WebGraphQLSource {
    #private;
    readonly operations: readonly WebGraphQLRuntimeOperation[];
    readonly execution: WebGraphQLExecution<TParameters, TResults>;
    constructor(configuration?: WebGraphQLConfig);
    get authenticated(): boolean;
    getOperation(idOrName: string): WebGraphQLRuntimeOperation | undefined;
    getVariables(idOrName: string): WebGraphQLParameters;
    setVariables<TName extends OperationName<TParameters, TResults>>(name: TName, variables: TParameters[TName]): void;
    getPage(idOrName: string): WebGraphQLPage | undefined;
    subscribe(listener: (change: WebGraphQLChange) => void): () => void;
    execute<TName extends OperationName<TParameters, TResults>>(name: TName, variables?: TParameters[TName]): Promise<TResults[TName]>;
    executePage<TName extends OperationOf<TParameters, TResults, WebGraphQLPage<unknown>>>(name: TName, options?: WebGraphQLPageOptions<TParameters[TName]>): Promise<Extract<TResults[TName], WebGraphQLPage<unknown>>>;
    executeMutation<TName extends OperationOf<TParameters, TResults, WebGraphQLMutationResult<unknown>>>(name: TName, variables?: TParameters[TName]): Promise<Extract<TResults[TName], WebGraphQLMutationResult<unknown>>>;
    executePageById(idOrName: string, options?: WebGraphQLPageOptions): Promise<WebGraphQLPage>;
    executeMutationById(idOrName: string, variables?: WebGraphQLParameters, options?: WebGraphQLMutationOptions): Promise<WebGraphQLMutationResult>;
    set onRequest(handler: WebGraphQLEventHandler<this> | null);
    set onSuccess(handler: WebGraphQLEventHandler<this> | null);
    set onError(handler: WebGraphQLEventHandler<this> | null);
    set onComplete(handler: WebGraphQLEventHandler<this> | null);
    dispose(): void;
}

export interface WebDataGridGraphQLConfiguration {
    readonly pageSize: number;
    readonly showPager: boolean;
    readonly crudEnabled: boolean;
    readonly insertOperationId: string | null;
    readonly updateOperationId: string | null;
    readonly deleteOperationId: string | null;
}

interface DataGridGraphQLSourceConfiguration extends WebDataGridGraphQLConfiguration {
    readonly apiClientId: string | null;
    readonly operationId: string | null;
}

export type WebDataGridMutationValues = Readonly<Record<string, WebGraphQLValue>>;

export type WebDataGridMutationKind = 'insert' | 'update' | 'delete';

export interface WebDataGridPendingChange {
    readonly id: number;
    readonly kind: WebDataGridMutationKind;
    readonly operationId: string;
    readonly row: WebGraphQLRow | null;
    readonly values: WebDataGridMutationValues;
    readonly outcome: 'pending' | 'uncertain';
}

export interface WebDataGridChangesEventDetail {
    readonly pendingChanges: readonly WebDataGridPendingChange[];
}

export interface WebDataGridSaveChangesEventDetail extends WebDataGridChangesEventDetail {
    readonly applied: number;
}

export interface WebDataGridSaveErrorEventDetail extends WebDataGridSaveChangesEventDetail {
    readonly change: WebDataGridPendingChange;
    readonly error: Error;
}

export type WebDataGridGraphQLEventHandler<TSender, TDetail> = (sender: TSender, event: CustomEvent<TDetail>) => void | Promise<void>;
